import type { MessageKey } from "@/lib/messages.en";

/**
 * Hebrew wording (modern Israeli Hebrew). Partial on purpose: Hebrew is not marked complete yet,
 * and every key that is missing here shows its English sentence (see docs/TRANSLATING.md and
 * `npm run i18n:status -- he`).
 *
 * Buttons and commands are in the infinitive or as a noun (שמירה, מחיקה), the way Hebrew software
 * speaks, which also keeps the interface free of grammatical gender. Numbers use Western digits
 * (see numberLocale in languages.ts). The layout is not mirrored for right-to-left yet, as with
 * Arabic; that is a separate change.
 *
 * Terms are kept the same across the interface (object/body = גוף, shape = צורה, part = חלק,
 * workplane = מישור עבודה, plane = מישור, sketch = סקיצה, extrude = שליפה, chamfer = שיפוע,
 * fillet = עיגול פינה, hole = חור, group = קבוצה, mesh = רשת משולשים, grid = רשת, face = פאה,
 * edge = קצה, overhang = תליה, thread = הברגה, build plate = משטח הדפסה, design = עיצוב,
 * section view = תצוגת חתך, mm = מ״מ). Printing words Israeli makers say in English stay as they
 * are pronounced or are translated plainly (פילמנט, סלייסר, מילוי, תמיכות, STL, G-code).
 */
