  "backups.missing": "הקובץ של הגיבוי הזה חסר בדפדפן.",
  "backups.openedName": "{name} ({when})",
  "backups.usage": "גיבויים: {count} · {size}",
  "backups.settingsHint": "כמה נשמרים: הגדרות → גיבויים",
  "backups.allowFolder": "מתן גישה לתיקייה",
  "backups.folderAllowed": "layerling יכול שוב לכתוב לתיקיית הגיבוי.",
  "backups.folderNotAllowed": "הדפדפן לא אישר את תיקיית הגיבוי; הגיבויים נשארים בדפדפן.",
  "backups.reminderNever": "העיצובים שלך עדיין לא גובו. הם נמצאים רק בדפדפן הזה: כדאי לגבות לקובץ ולשמור אותו במקום נוסף.",
  "backups.reminderAfterDays": "העיצובים שלך לא גובו כבר {days} ימים. כדאי לגבות לקובץ ולשמור אותו במקום נוסף.",
  "backups.backUpNow": "גיבוי עכשיו",
