  "backups.overwriteCountHint": "לפני ששמירה כותבת מעל קובץ .lyl, הקובץ כפי שהיה נשמר. כשיש יותר מדי, הישן ביותר נמחק.",
  "backups.snapshotMinutes": "מצבים בזמן העבודה",
