  "customKeys.title": "מקשים משלך",
  "customKeys.intro": "אפשר לשים כל פקודה מחיפוש הפקודות על מקש משלך: כלי, צורה, מירכוז במישור העבודה, לוח הצורות. המקשים שלך נשארים בדפדפן הזה.",
