  "interactiveHelp.nothing": "אין כאן מה להסביר. יש להצביע על כפתור, שדה, ידית או חלון.",
  "interactiveHelp.loading": "מחפש במדריך...",
  "interactiveHelp.noIndex": "המדריך עדיין לא זמין כאן. אפשר לפתוח אותו מהסקירה.",
  "interactiveHelp.panelOnly": "לחלק הזה אין שם משלו. סימן השאלה של החלון שלו פותח את החלק במדריך שעוסק בו.",
  "interactiveHelp.sectionOnly": "במדריך יש סעיף על החלק הזה.",
