  "interactiveHelp.also": "גם במדריך",
  "interactiveHelp.search": "חיפוש במדריך",
  "interactiveHelp.open": "פתיחה במדריך",
  "interactiveHelp.started": "עזרה אינטראקטיבית פעילה: לחיצה על כפתור, שדה או חלון מציגה הסבר. Esc ליציאה.",
  "interactiveHelp.ended": "עזרה אינטראקטיבית כבויה",
  "shortcuts.interactiveHelp": "הפעלה או כיבוי של עזרה אינטראקטיבית",
  "shortcuts.focusMode": "מצב מיקוד מופעל או כבוי (מסתיר את שורת הכותרת והכותרת התחתונה)",
  "installHint.chromium": "ההתקנה דרך הסמל מימין לשורת הכתובת, או מתפריט הדפדפן תחת «התקנה כאפליקציה».",
  "installHint.safariMac": "ב-Safari: תפריט קובץ ← «הוספה ל-Dock».",
  "installHint.ios": "ב-Safari: סמל השיתוף ← «הוספה למסך הבית».",
  "installHint.firefoxWindows": "ב-Firefox: הסמל „הוספת לשונית לשורת המשימות” בצד שורת הכתובת (לא בחלון פרטי).",
  "installHint.firefox": "Firefox לא יכול להתקין כאן אפליקציות – layerling עדיין נפתח בכרטיסייה גם בלי אינטרנט.",
  "welcome.moreLanguagesTitle": "השפה שלך",
  "welcome.moreLanguagesBody": "התוכנה והמדריך שלה מדברים אנגלית, גרמנית ועוד 19 שפות; רשימת השפות נמצאת בפינה העליונה הימנית, ובהגדרות בדף הפתיחה.",
  "welcome.moreOfflineTitle": "עובד בלי אינטרנט",
  "welcome.moreOfflineBody": "אחרי הביקור הראשון layerling נפתח גם בלי אינטרנט - אפשר להתקין אותו כמו תוכנה רגילה, והעיצובים נשארים במחשב שלך.",
  "welcome.moreAiTitle": "בנייה עם בינה מלאכותית",
  "welcome.moreAiBody": "דרך ממשק MCP עוזר בינה מלאכותית יכול ליצור ולערוך צורות, בעורך שהוא פותח בעצמו. לשם כך צריך עותק שמריצים בעצמכם (npm run dev, או תמונת ה-Docker); ב-layerling.com החיבור לבינה מלאכותית כבוי.",
  "welcome.morePointsTitle": "נקודות ייחוס",
  "welcome.moreSearchTitle": "חיפוש פקודות",
  "welcome.moreSimplifyTitle": "פישוט רשתות משולשים",
  "welcome.moreSimplifyBody": "רשת מיובאת עם מספר עצום של משולשים מצטמצמת לחלק קטן, עם תצוגת לפני ואחרי ומחוון - כך שחיתוך, קיבוץ וגרירה נשארים חלקים.",
  "welcome.moreHistoryTitle": "היסטוריה",
  "welcome.moreLookTitle": "מראה לפי הטעם",
  "welcome.moreLookBody": "הרקע ומישור העבודה, חיצי הצירים ל-X, Y ו-Z, קווי קצה על כל גוף, צבעי הסקיצה, והניגודיות, הצללים וכיוון האור נקבעים בהגדרות - למשל כדי שגופים כהים לא יתמזגו זה בזה. במחשבים איטיים, המצב המהיר מכבה בבת אחת כל מה שכבד.",
  "welcome.moreControlsTitle": "עכבר ועכבר תלת-ממד",
  "welcome.moreControlsBody": "מאפשר לכפתורי העכבר לפעול כמו ב-Bambu Studio וב-OrcaSlicer לפי הרצון - גרירה שמאלית על שטח ריק מסובבת את התצוגה, הכפתור הימני מזיז אותה - ומנווט את התצוגה עם SpaceMouse ב-Chrome וב-Edge.",
  "welcome.moreTabletTitle": "בטאבלט",
  "welcome.moreTabletBody": "אצבע אחת עובדת על העיצוב כמו כפתור העכבר השמאלי, שתי אצבעות מגדילות ומזיזות את התצוגה; מקלדת Bluetooth מביאה את קיצורי המקשים.",
  "welcome.moreHistoryBody": "חזרה לכל מצב קודם של הפרויקט עם מחוון, בלי לשנות דבר - ייצוא המצב הזה, פרויקט חדש ממנו או החזרת גופים בודדים ממנו. «ביטול פעולה» ו«ביצוע חוזר» מציגים את השלב שהם מבטלים, עם המידה שלו, ורשימה מציגה כל שלב לקפיצה אליו.",
  "welcome.moreDrawingTitle": "שרטוט לסדנה",
  "welcome.moreDrawingBody": "ייצוא → שרטוט: מבט מלפנים, מלמעלה ומהצד ב-1:1 על גיליון ISO, עם מידות כלליות, קצוות נסתרים וטבלה של הקידוחים העגולים – כ-PDF או SVG, להדפסה או לעבודה במחרטה ובכרסומת. המבט העליון כ-SVG או DXF הולך לחותך הלייזר, עם גשרי שבלונה שמחזיקים את המרכז של o או b לפי הרצון. הדפיסו את ה-PDF על נייר והניחו עליו את החלק האמיתי: כך בודקים את המידות לפני הדפסת התלת-ממד.",
  "welcome.moreSearchBody": "Ctrl+K והקלדת שם של כלי, צורה או פקודה קופצים ישר אליהם - באנגלית או בגרמנית, עם קיצורי המקשים לצד כל אחד. גם הגופים בעיצוב נמצאים לפי שם. כל אחד מהם יכול לשבת גם על מקש משלך, וכפתורים שלא משתמשים בהם אפשר להוריד מסרגל הכלים בהגדרות - החיפוש עדיין מוצא אותם.",
  "welcome.moreHelpTitle": "עזרה אינטראקטיבית",
  "welcome.moreHelpBody": "Shift+F1 או סימן השאלה, ואז לחיצה על כל כפתור, שדה או חלון: חלון קטן מציג את החלק במדריך שעוסק בו.",
  "welcome.morePointsBody": "לחיצה ימנית על גוף מסמנת את המרכז, הפינות או אמצעי הקצוות שלו בנקודות שלא מודפסות וצורות נצמדות אליהן - ואז אפשר להציב חור בדיוק במרכז של חלק אחר.",
  "welcome.videosTitle": "סרטונים על layerling",
  "welcome.videosHint": "נוצרו על ידי אחרים, לא על ידי הפרויקט. הקישורים פותחים את YouTube בכרטיסייה חדשה; שום דבר לא נטען משם עד הלחיצה.",
  "welcome.help": "בעורך, קבוצת «עזרה» מכילה מדריך קצר ואת רשימת כל קיצורי המקשים. בכותרת התחתונה, «דיווח על באג» שומר את העיצוב עם כל מה שנדרש לדיווח בפורום או ב-GitHub.",
  "welcome.guideLink": "המדריך המלא למשתמש, עם תמונות",
  "welcome.guideUrl": "/madrich/index.html",
