  "flexi.fold": "קיפול למעלה ולמטה ב-",
  "flexi.helpFold": "הגוף נחתך לרוחבו לרצועות, עם ציר שמודפס במקומו בכל חיתוך, כך שהרצועות מתקפלות למעלה ולמטה אחרי ההדפסה, כמו מחזיק מפתחות גמיש. יש להשכיב את הגוף על המשטח קודם; היכן שהצירים נמצאים הוא צריך להיות לפחות כ-5 מ״מ גובה ו-15–20 מ״מ רוחב.",
