  "flexi.error.notClosed": "הגוף אינו סגור, ולכן אי אפשר לחתוך אותו לחוליות. יש לסגור או לתקן אותו קודם.",
  "flexi.error.tooShort": "המפרקים לא נכנסים לאורך הגוף. כדאי לקחת פחות מפרקים או להזיז את המפרק הראשון והאחרון פנימה.",
  "flexi.error.tooThin": "למפרק {joint} אין מקום: הגוף שם ברוחב {size} מ״מ בלבד. יש להרחיב את הגוף שם, לקחת מפרק קטן יותר או להזיז את המפרקים.",
  "flexi.error.foldTooThin": "למפרק {joint} אין מקום: הגוף שם ברוחב {size} מ״מ בלבד, ציר קיפול צריך כ-{need} מ״מ. יש להרחיב את הגוף שם או להזיז את המפרקים.",
  "flexi.error.tooFlat": "למפרק {joint} אין מקום: הגוף שם בגובה {size} מ״מ בלבד. מפרק צריך לפחות כ-3 מ״מ, עדיף 6 מ״מ ומעלה.",
  "flexi.error.tooClose": "מפרק {joint} קרוב מדי לקודם: המפרקים צריכים כ-{size} מ״מ ביניהם. כדאי לקחת פחות מפרקים או מפרק קטן יותר.",
  "flexi.error.empty": "חוליה {link} תהיה ריקה. כדאי לקחת פחות מפרקים.",
