  "status.flexiMade": "החוליות הגמישות נוצרו: {links} חוליות עם {joints} מפרקים, כל אחד מתנדנד עד {swing}° לצד. להדפיס אותן כפי שהן מונחות, בחלק אחד.",
  "status.flexiFolded": "החוליות הגמישות נוצרו: {links} רצועות עם {joints} צירים, כל אחד מתקפל עד {swing}° למעלה ולמטה. להדפיס אותן כפי שהן מונחות, בחלק אחד.",
