  "lid.help": "המכסה עוקב אחרי קו המתאר של הגוף והפתח שבחלקו העליון. יש להפוך קודם את הגוף לחלול עם חלק עליון פתוח. המכסה יוצא לידו, הפוך עם הלוח למטה, מוכן להדפסה.",
