  "lid.type.capHint": "לוח רחב מהגוף בעובי דופן עם שפה מתחתיו שעוטפת מבחוץ.",
  "lid.type.bothHint": "לוח רחב מהגוף בעובי דופן עם שפה לתוך הפתח ושפה מבחוץ: דופן הגוף יושבת בחריץ ביניהן, כמו בקופסת אוכל.",
  "lid.type.flatHint": "רק לוח בגודל הגוף, להנחה מעל או להדבקה.",
  "lid.type.screwHint": "מכסה עם הברגה בתוך השפה שלו שמתברג על אותה הברגה בחלק העליון החיצוני של הגוף, כמו צנצנת. לגוף עגול: גליל, צינור, סיר עגול.",
  "lid.type.screwInHint": "לוח על השפה עם פקק מוברג מתחתיו שמתברג לאותה הברגה בתוך פתח הגוף. לגוף עגול עם פתח עגול: גליל, צינור, סיר עגול.",
  "lid.type.bayonetHint": "מכסה שנדחף מטה מעל בליטות בחלק העליון החיצוני של הגוף ומסובב לנעילה, כמו חיבור כידון. לגוף עגול: גליל, צינור, סיר עגול.",
  "lid.type.slideHint": "לוח שמחליק פנימה דרך דופן אחת, והשוליים שלו נעים בחריצים בשלוש האחרות, כמו בקלמר עץ. לקופסה עם דפנות ישרות.",
