  "lid.threadOffset": "היסט ההברגה",
  "lid.threadOffsetHint": "כמה מתחת לשפה ההברגה מתחילה. ב-0 היא מתחילה בשפה; יותר משאיר קטע חלק של הדופן מעליה, ושפת המכסה (או הפקק) יורדת באותה מידה.",
  "lid.screwHint": "הגוף מקבל הברגה בעומק {depth} מ״מ בחלק העליון החיצוני, והמכסה את אותה הברגה בתוך השפה שלו, שיורדת {height} מ״מ. הדפנות ב-45°, כך ששניהם מודפסים בלי תמיכות.",
  "lid.screwInHint": "הגוף מקבל הברגה בעומק {depth} מ״מ בתוך הפתח, והמכסה את אותה הברגה על פקק מתחת ללוח, שיורד {height} מ״מ. היכן שיש מקום, הפקק הוא טבעת עם דופן של {wall} מ״מ. הדפנות ב-45°, כך ששניהם מודפסים בלי תמיכות.",
  "lid.screwThreadName": "{name} הברגה",
  "lid.threadStandard": "הברגה",
  "lid.threadStandard.own": "מותאם אישית",
  "lid.threadStandardHint.pco1881": "רוב בקבוקי המים והמשקאות הקלים: צוואר 28 מ״מ עם ההברגה הקצרה.",
  "lid.threadStandardHint.pco1810": "בקבוקי משקה ישנים: צוואר 28 מ״מ עם ההברגה הגבוהה.",
  "lid.threadStandardHint.gl45": "בקבוקי מעבדה עם הברגת GL 45 (DIN 168).",
  "lid.threadStandardHint.mason70": "צנצנות מייסון עם פה רגיל. להברגה שלהן אין שרטוט מפורסם, והמידות נמדדו: כדאי לנסות את המכסה על הצנצנת קודם.",
  "lid.threadStandardHint.mason86": "צנצנות מייסון עם פה רחב. להברגה שלהן אין שרטוט מפורסם, והמידות נמדדו: כדאי לנסות את המכסה על הצנצנת קודם.",
  "lid.screwStandardHint": "המכסה מתאים לצוואר {standard}: {major} מ״מ קוטר ההברגה, {pitch} מ״מ לסיבוב; הוא יורד {depth} מ״מ. גוף שהחלק העליון שלו ברוחב הצוואר מתחת להברגה ({from} עד {to} מ״מ) מקבל את הברגת הצוואר; כל אחר נשאר כמו שהוא, ונוצר רק המכסה. הדפנות לפי התקן, תלולות מ-45°.",
  "lid.neckMeasuring": "מודד את החלק העליון של הגוף…",
  "lid.neckFits": "החלק העליון של הגוף: קוטר {measured} מ״מ. צוואר {standard} הוא {from} עד {to} מ״מ מתחת להברגה, ולכן הגוף מקבל גם את ההברגה.",
  "lid.neckSize": "החלק העליון של הגוף: קוטר {measured} מ״מ. צוואר {standard} צריך {from} עד {to} מ״מ מתחת להברגה, ולכן נוצר רק המכסה.",
  "lid.neckNotRound": "החלק העליון של הגוף אינו עגול, ולכן נוצר רק המכסה.",
  "lid.neckFit": "התאמת הגוף לצוואר",
  "lid.neckFitHint": "הופך את הגוף לקוטר {diameter} מ״מ ושומר על הגובה, כך ש«יצירת מכסה» נותנת לו את ההברגה.",
  "lid.neckFitting": "מתאים את הגוף…",
  "lid.neckFitByHand": "בקוטר {diameter} מ״מ בחלק העליון הגוף יקבל גם את ההברגה.",
  "lid.bayonetLugs": "בליטות",
  "lid.bayonetTurn": "סיבוב (0 = אוטומטי)",
  "lid.bayonetTurnHint": "עד 90°, רבע סיבוב, ששתי בליטות משאירות לו מקום. יותר בליטות או גוף קטן משאירים פחות מקום לחריצים ולעצירות ביניהם: סיבוב שלא מתאים מוגבל אז למה שמתאים, ושורת המצב אומרת זאת.",
  "lid.bayonetAxialGap": "מרווח בגובה",
  "lid.bayonetDetent": "גובה הנקישה",
  "lid.bayonetDetentHint": "צלע קטנה מאחורי כל בליטה נעולה, שהיא נוקשת מעליה, כדי שהמכסה לא יסתובב חזרה מעצמו; 0 ללא, פחות אם המכסה מסתובב קשה מדי.",
  "lid.bayonetHint": "{count} בליטות בחלק העליון החיצוני של הגוף, לפי הקוטר שלו, וחריץ בצורת L לכל אחת בתוך שפת המכסה. לדחוף את המכסה מטה מעליהן ולסובב {turn}° עם כיוון השעון עד הנקישה. הבליטות והחריצים משופעים ב-45° מלמטה, כך ששניהם מודפסים בלי תמיכות.",
  "lid.bayonetLugsName": "{name} בליטות",
  "lid.slideSide": "מחליק פנימה מ-",
  "lid.slideHint": "שולי המכסה נעים בחריצים בשלוש דפנות; הרביעית נחתכת עד תחתית המכסה, כך שהמכסה מחליק מעליה והקצה שלו ממלא את החיתוך. החלק העליון של החריצים משופע ב-45°, כך שהקופסה מודפסת זקופה והמכסה על הצד העליון שלו, שניהם בלי תמיכות.",
  "lid.slideFrame": "מסגרת מעל המכסה",
  "lid.slideFrameHint": "כמה המכסה יושב מתחת לשפה, כשהדפנות עומדות סביבו כמסגרת. 0: המכסה בגובה השפה.",
  "lid.slideHintFrame": "המכסה יושב מתחת לשפה, השוליים שלו נעים בחריצים בשלוש דפנות; הוא מחליק פנימה דרך חריץ ברביעית, ששומרת על מלוא הגובה מעליו, והקצה שלו ממלא את החריץ. הקופסה מודפסת זקופה, עם גישור מעל החריץ; המכסה מודפס על הצד העליון שלו בלי תמיכות.",
  "lid.slideBumpHint": "בליטה קטנה מתחת לקצה המכסה נוקשת מעבר לשפה הפנימית של הדופן שהוא מחליק דרכה, כדי שהמכסה לא יחליק החוצה מעצמו. גובה הבליטה הוא כמה היא בולטת מתחת למכסה: פחות לקופסה קטנה, יותר לנקישה חזקה.",
  "lid.slideGroovesName": "{name} חריצי מכסה",
  "lid.tether": "רצועת קשירה",
  "lid.tetherHint": "שומרת את המכסה עם הגוף כשהוא פתוח, כמו בבקבוק משקה: שתי טבעות פתוחות המחוברות ברצועה, מודפסות שטוח ליד המכסה, עדיף ב-PETG או TPU (ב-PLA היא עומדת רק בכמה כיפופים). הטבעת הגדולה ננעלת על המכסה מלמטה, מתחת לצווארון סביב החלק העליון שלו, והקטנה על הגוף מתחת למכסה, היכן שחרוז מחזיק אותה. שתיהן מסתובבות בחופשיות, כך שהמכסה עדיין מתברג ונפתח.",
  "lid.tetherName": "{name} רצועת קשירה",
  "lid.tetherBeadName": "{name} חרוז רצועה",
  "lid.flipTop": "מכסה נפתח (Flip-top)",
  "lid.flipTopOpening": "פתח",
