  "shell.errorRoundedEdges": "לקופסה הזו יש קצוות עליונים ותחתונים מעוגלים, והדופן צריכה להיות דקה בבירור מהעיגול. יש לבחור דופן דקה יותר, או לקבוע את עיגול הקצוות העליונים והתחתונים ל-0 לפני ההפיכה לחלול. אם זה עדיין נכשל, «דיווח על באג» בכותרת התחתונה שומר את העיצוב לדיווח.",
