  "guide.edges.offset": "היסט מזיז כל פאה של גוף באותו מרחק, החוצה או פנימה. הגדלת עותק ושמירתו כחור נותנת מרווח להתאמת לחיצה, והקטנת גוף נותנת פין שצריך להיכנס לחור. גופים שהם רק רשת משולשים לרוב אי אפשר להסיט.",
  "edge.revertSurfaceTexture": "מרקם משטח (עומק {size} מ״מ)",
  "deleteFace.title": "מחיקת פאה",
  "deleteFace.subtitle": "פאות שכנות סוגרות את הפער",
  "deleteFace.help": "לחיצה על הפאות למחיקה; לחיצה נוספת מוציאה פאה שוב. Shift לוקח את כל הדופן: את הפאה ואת כל הפאות שהיא ממשיכה אליהן בצורה חלקה, למשל את כל הפאות של דופן חור. הפאות שמסביב גדלות עד שהפער נסגר: עיגול פינה, חור או בליטה נעלמים, והגוף נשאר מדויק. פאות דקות כשערה בין פאות באותו מישור נמחקות עם הפאות שנבחרו.",
  "deleteFace.preparing": "קורא את הפאות…",
  "deleteFace.countNone": "עדיין לא נבחרה פאה",
  "deleteFace.countOne": "נבחרה פאה אחת",
  "deleteFace.countMany": "פאות שנבחרו: {count}",
  "deleteFace.thinOne": "נלקחה גם: פאה דקה כשערה אחת",
  "deleteFace.thinMany": "נלקחו גם: {count} פאות דקות כשערה",
  "deleteFace.apply": "מחיקה",
  "deleteFace.working": "מוחק פאות…",
  "deleteFace.cancel": "ביטול מחיקת הפאות",
  "deleteFace.errorUnchanged": "אי אפשר למחוק את הפאות האלה: הפאות שמסביבן לא סוגרות את הפער. יש לבחור כל פאה של מה שצריך להיעלם, כמו כל הפאות של עיגול פינה או כל הדופן של חור, ושום פאה של הגוף עצמו. אם כל הפאות של מה שצריך להיעלם כבר נבחרו, ייתכן שאי אפשר לסגור כאן את הפער בכלל: יש למלא אותו בגוף נוסף - או, במקום שמשהו בולט, לחתוך אותו בגוף שהפך לחור - ולקבץ את השניים.",
  "deleteFace.errorMesh": "לגוף הזה אין פאות מדויקות למחיקה: layerling שומר אותו כרשת משולשים, כמו STL, OBJ או 3MF מיובא, גוף מפוצל, עטוף או מפושט, או צורה מפורטת מאוד כמו טקסט ארוך. קובץ STL, OBJ או 3MF מיובא מקבל אותן בדרך כלל בעזרת „הפיכה למדויק”: יש ללחוץ על כך קודם ואז לנסות שוב. חלק שיובא כ-STEP יש לו פאות מדויקות.",
  "deleteFace.errorResized": "גודל הגוף הזה שונה כש«שמירת גודל הקצה בשינוי גודל» הייתה פעילה, ולכן הפאות המדויקות שלו כבר לא תואמות לגודלו. יש לבטל את שינוי הגודל, למחוק את הפאות, ואז לשנות שוב את הגודל.",
  "deleteFace.errorProjectChanged": "הגוף או הפרויקט השתנו בזמן מחיקת הפאות; כדאי לנסות שוב.",
  "deleteFace.errorFailed": "לא ניתן היה למחוק את הפאות. כדאי לבחור פאות אחרות.",
  "deleteFace.errorNoFaces": "לא ניתן היה לקרוא את הפאות של הגוף הזה. יש לסגור את הכלי ולפתוח אותו שוב.",
  "deleteFace.errorTooSlow": "מחיקת הפאות האלה ארכה יותר מדי ונעצרה אחרי 45 שניות; שום דבר לא השתנה. ליבת ה-CAD לא מסתדרת עם הפאות האלה בחלק הזה: כדאי לבחור פאות אחרות, או פחות.",
  "status.facesDeletedOne": "פאה אחת נמחקה",
