  "editor.bugReport": "דיווח על באג",
  "editor.bugReportHint": "שמירת דיווח על באג כ-ZIP: העיצוב עם הגרסה, הדפדפן וההודעות האחרונות, לצירוף בפורום או ב-GitHub",
