  "status.bugReportBuilding": "בונה את הדיווח על הבאג…",
  "status.bugReportSaved": "הדיווח על הבאג נשמר כ-ZIP. אפשר לצרף את הקובץ לפוסט בפורום או ב-GitHub.",
  "editor.group.help": "עזרה",
