  "thread.axialClearanceHint": "חופש נוסף לאורך ההברגה, במ״מ, מעבר למרווח: כל שן של האום נעשית דקה בערך הזה בעוד הקוטר נשאר. להברגה שמסתובבת בחופשיות ולא מקשקשת לצדדים: לשמור על המרווח סביב 0.2 עד 0.3 ולקבוע כאן 0.2. ב-0 החופש בא מהמרווח בלבד, שפותח את הדפנות רק בערך בחצי.",
