  "status.gridfinityKeysNone": "ללוח הזה אין כיסים מאחור או מימין, כי הצדדים האלה מרופדים, ולכן הוא לא מביא מפתחות. קביעת הריפוד של אחד מהם ל-0 נותנת לו כיסים.",
