  "inspector.gridfinitySplit": "פיצול להתאמה למדפסת",
  "gridfinity.splitHint": "חותך את הלוח על קווי התאים ל-{count} לוחות שמתאימים ל-{printer}, כל אחד עם זנב סנונית, ומסדר את המפתחות לפניהם.",
  "gridfinity.splitHintPuzzle": "חותך את הלוח על קווי התאים ל-{count} לוחות שמתאימים ל-{printer}, מחוברים בפאזל של GridFlock: לשוניות בצדדים החתוכים מאחור ומימין, שקעים מלפנים ומשמאל.",
  "gridfinity.splitHintPuzzleKeys": "חותך את הלוח על קווי התאים ל-{count} לוחות שמתאימים ל-{printer}, מחוברים בפאזל של GridFlock: לשוניות בצדדים החתוכים מאחור ומימין, שקעים מלפנים ומשמאל. מפתחות זנב הסנונית שלהם מסודרים לפניהם.",
  "status.gridfinitySplitPuzzle": "פוצל ל-{count} לוחות שמתאימים ל-{printer}, מחוברים בפאזל של GridFlock בצדדים החתוכים. יש ללחוץ את החלקים יחד מלמעלה. הלוחות מונחים היכן שהתאים שלהם היו, כך שכל אחד שחורג מהמשטח מסומן עד שמזיזים אותו, או מסובבים ברבע, עליו.",
  "status.gridfinitySplit": "פוצל ל-{count} לוחות שמתאימים ל-{printer}. מפתחות לפניהם: {keys}. יש ללחוץ כל אחד לכיס לרוחב תפר מלמטה עד הנקישה. הלוחות מונחים היכן שהתאים שלהם היו, כך שכל אחד שחורג מהמשטח מסומן עד שמזיזים אותו, או מסובבים ברבע, עליו.",
