  "inspector.surfaceCarbonHint": "רוחב רצועה חוצה 0: ברוחב הרצועות הזקופות. רחב או צר יותר נותן אריגה לא אחידה. סביב גוף רוחב הרצועה מעוגל מעט כדי שהאריגה תיסגר.",
  "inspector.surfaceSeed": "סידור",
  "inspector.surfaceSeedHint": "מספר אחר מסדר את התאים או הגרעינים מחדש.",
  "inspector.surfaceHammeredHint": "שקעים עגולים כמו מכות פטיש, כל אחד מעט שונה בגודל ובעומק. המרווח קובע כמה קרובים הם, גודל השקע כמה הם חופפים, ומספר אחר תחת «סידור» מפזר אותם מחדש. הפרופיל «עגול» מרכך אותם.",
  "inspector.surfaceImage": "תמונה",
  "inspector.surfaceImageLoad": "טעינת תמונה משלך…",
  "inspector.surfaceImageHint": "בהיר הופך למלוא העומק, כהה נשאר כמו שהוא. ציור כהה על רקע שקוף, כמו קווים שחורים ב-SVG, נספר לפי הקווים שלו: הם הופכים למלוא העומק. התמונה שלך נשמרת עם העיצוב באפור, לכל היותר 512 נקודות לצד; אריח ברוחב שנקבע ובגובה של התמונה לרוחב הזה.",
  "inspector.surfaceTileHeight": "גובה אריח (0 = כמו התמונה)",
  "inspector.surfaceImageHeight": "גובה התמונה",
  "inspector.surfaceImageOnceHint": "התמונה מוטבעת פעם אחת, כמו מדבקה: «מסביב» ו«גובה» ממקמים את המרכז שלה, כמו לטקסט. מחוצה לה המשטח נשאר חלק; «עומק» ו«כיוון» קובעים כמה היא בולטת או נחתכת. גובה תמונה 0 שומר על הפרופורציות שלה. כשנבחרו פאות, היא תמיד נוחתת עליהן.",
