  "export.obj.description": "רשת תלת-ממד אוניברסלית",
  "export.obj.note": "פורמט רשת תואם באופן רחב למידול, רינדור והחלפה. הצבעים נשמרים בקודקודים, ש-Bambu Studio ו-OrcaSlicer קוראים.",
  "export.step.description": "CAD / B-Rep",
  "export.step.note": "שומר קופסאות, גלילים, כדורים וחרוטים כגאומטריית CAD מדויקת, יחד עם כל מה שהקצוות שלו עוגלו או שופעו וגופים שנכנסו כ-STEP. גם הברגות, קפיצים וגלגלי שיניים יוצאים כגוף המדויק שלהם. גם צורות מתחדדות, מוטות ומפותלות יוצאות מדויק. גם טקסט יוצא מדויק, אות אחר אות עם העקומות של הגופן. רשתות מיובאות יוצאות כשהן הופכות למדויקות, המישורים, הגלילים, החרוטים, הכדורים והטורוסים שלהן כפאות אמיתיות; רשת חופשית, כמו דמות, יוצאת כ-STL.",
  "export.svg.description": "וקטור מבט עליון",
  "export.svg.note": "מייצא צללית נקייה במבט עליון במילימטרים, כולל חורים וקווי מתאר מעוקלים.",
  "export.svg.noteFootprint": "מייצא רק את קווי המתאר היכן שהגופים עומדים על מישור העבודה, כקווים במילימטרים, לחיתוך לייזר ולתבניות.",
  "export.svg.noteEdges": "מייצא את הקצוות שנראים מלמעלה כקווים במילימטרים, כל גוף בצבע שלו: קווי מתאר, חורים, כיסים וחריטות, כל שטח סגור, לחריטת לייזר ולפלוטרים.",
