  "export.dxf.noteFootprint": "מייצא רק את קווי המתאר היכן שהגופים עומדים על מישור העבודה, לסדנאות חיתוך לייזר: קווים, קשתות אמיתיות ועיגולים בשכבה 0 בלבן, במילימטרים.",
  "export.lyl.description": "פורמט העיצוב של layerling",
