  "mold.kindHint.twoPart": "תבנית קשיחה בשני חצאים להדפסה וליציקה ישירה: שרף, גבס, שעווה, סבון, שוקולד או בטון. מפתחות מיישרים את החצאים, משפך ופתחי אוורור מכניסים את החומר ומוציאים את האוויר.",
  "mold.kindHint.box": "מסגרת ולוח בסיס ליציקת סיליקון סביב המקור המודפס. תבנית הסיליקון מעתיקה אז כל פרט ומשחררת חיתוכים תחתונים שהיו נתקעים בתבנית קשיחה.",
